const toNumber = (value) => {
  const normalized = Number(value);
  return Number.isFinite(normalized) ? normalized : 0;
};
const message = $json.message && typeof $json.message === 'object' && !Array.isArray($json.message) ? $json.message : {};
const chat = message.chat && typeof message.chat === 'object' ? message.chat : {};
const sender = message.from && typeof message.from === 'object' ? message.from : {};
return [{ json: {
  workflow_id: 'WF-001',
  workflow_version: '2.0',
  telegram_update_id: toNumber($json.update_id),
  telegram_chat_id: toNumber(chat.id),
  telegram_user_id: toNumber(sender.id),
  telegram_text: typeof message.text === 'string' ? message.text : '',
  received_at: new Date().toISOString(),
} }];

const text = $json.telegram_text.trim();
const match = text.match(/^\/([a-zA-Z0-9_-]+)(?:@[a-zA-Z0-9_]+)?(?:\s+([\s\S]*))?$/u);
const command = match ? match[1].toLowerCase() : '';
const argumentText = match?.[2]?.trim() ?? '';
const commandArgs = [];
let token = '';
let quote = '';
let escaped = false;
let parseSuccess = Boolean(match);

if (parseSuccess && argumentText) {
  for (const character of argumentText) {
    if (escaped) {
      token += character;
      escaped = false;
    } else if (character === '\\' && quote) {
      escaped = true;
    } else if (quote) {
      if (character === quote) quote = '';
      else token += character;
    } else if (character === '"' || character === "'") {
      quote = character;
    } else if (/\s/u.test(character)) {
      if (token) {
        commandArgs.push(token);
        token = '';
      }
    } else {
      token += character;
    }
  }
  if (escaped || quote) parseSuccess = false;
  else if (token) commandArgs.push(token);
}

return [{ json: {
  ...$json,
  command,
  argument_text: argumentText,
  command_args: parseSuccess ? commandArgs : [],
  parse_success: parseSuccess,
} }];

const targets = { new: 'WF-002', status: 'WF-003', help: 'WF-004' };
let validationError = '';
if (!$json.parse_success) {
  validationError = $json.telegram_text.trim().startsWith('/')
    ? 'Telegram command syntax is malformed.'
    : 'Message must begin with a Telegram command such as /new.';
} else if (!Object.prototype.hasOwnProperty.call(targets, $json.command)) {
  validationError = `Unsupported command: /${$json.command}`;
}
const isValid = validationError === '';
return [{ json: {
  ...$json,
  route: isValid ? `command.${$json.command}` : 'command.invalid',
  target: isValid ? targets[$json.command] : '',
  is_valid: isValid,
  validation_error: validationError,
} }];
